typedef unsigned int u_int;
typedef unsigned long long u_long;
struct nglTexture;
struct nglFixedString { u_int Data[2]; };
struct nglMaterialInfo;
struct nglMaterial {
  u_int Flags; nglTexture* Map; nglTexture* LightMap; nglTexture* DetailMap; nglTexture* EnvironmentMap;
  u_int Pad0; nglFixedString MapName; int MapBlendMode; int MapBlendModeConstant;
  nglFixedString LightMapName; int LightMapBlendMode; int LightMapBlendModeConstant;
  nglFixedString DetailMapName; int DetailMapBlendMode; int DetailMapBlendModeConstant;
  float DetailMapUScale, DetailMapVScale, DetailMapRange, DetailMapAlphaClamp;
  nglFixedString EnvironmentMapName; int EnvironmentMapBlendMode; int EnvironmentMapBlendModeConstant;
  u_int SpecularColor; float SpecularPower, SpecularIntensity; u_int Color, MaterialID;
  float AlphaFalloff, ForcedSortDistance, ScrollU, ScrollV; nglMaterialInfo* Info;
  float MapMipRatio, LightMapMipRatio; u_int UserFlags, Pad[2];
};
enum {
  NGLMAT_BILINEAR_FILTER=0x1000, NGLMAT_TRILINEAR_FILTER=0x2000, NGLMAT_ANTIALIAS=0x4000,
  NGLMAT_CLAMP_U=0x10000, NGLMAT_CLAMP_V=0x20000, NGLMAT_FORCE_Z_WRITE=0x80000,
  NGLMAT_ENV_CYLINDER=0x400000, NGLMAT_LIGHT_CLAMP_U=0x1000000, NGLMAT_LIGHT_CLAMP_V=0x2000000,
  NGLMAP_POINT_FILTER=0, NGLMAP_BILINEAR_FILTER=1, NGLMAP_TRILINEAR_FILTER=2,
  NGL_GS_CLAMP_1=8, NGL_GS_PRMODE=27,
  NGLPASS_DIFFUSE, NGLPASS_DETAIL, NGLPASS_ENVIRONMENT, NGLPASS_LIGHT
};
#define SCE_GS_SET_CLAMP(wms,wmt,minu,maxu,minv,maxv) ((u_long)(wms)|((u_long)(wmt)<<2)|((u_long)(minu)<<4)|((u_long)(maxu)<<14)|((u_long)(minv)<<24)|((u_long)(maxv)<<34))
#define SCE_GS_SET_PRIM(prim,iip,tme,fge,abe,aa1,fst,ctxt,fix) ((u_long)(prim)|((u_long)(iip)<<3)|((u_long)(tme)<<4)|((u_long)(fge)<<5)|((u_long)(abe)<<6)|((u_long)(aa1)<<7)|((u_long)(fst)<<8)|((u_long)(ctxt)<<9)|((u_long)(fix)<<10))
#define START_PROF_TIMER(timer)
#define STOP_PROF_TIMER(timer)
#define NGL_ASSERT(condition,message) ((void)0)
void nglVif1StartMaterialKick();
void nglVif1AddSetBlendMode(u_int,u_int,bool);
void nglVif1AddSetTexture(nglTexture*,u_int,float);
void nglVif1AddGSReg(u_int,u_long);
void nglVif1EndMaterialKick(u_int*&,u_int&);

void nglVif1BakeMaterialPass( u_int*& Packet, u_int& CmdListDataPtr, nglMaterial* Material, u_int MaterialFlags, u_int Pass )
{
  START_PROF_TIMER( proftimer_section_setup_material );

  // Per-pass variables.
  u_int Mode, Fix;
  u_long Clamp;
  nglTexture* Map;
  float MipRatio;

  switch ( Pass )
  {
  case NGLPASS_DIFFUSE:
    Clamp = SCE_GS_SET_CLAMP( ( MaterialFlags & NGLMAT_CLAMP_U ) != 0, ( MaterialFlags & NGLMAT_CLAMP_V ) != 0, 0, 0, 0, 0 );
    Map = Material->Map; MipRatio = Material->MapMipRatio;
    Mode = Material->MapBlendMode; Fix = Material->MapBlendModeConstant;
    break;
  case NGLPASS_DETAIL:
    Clamp = SCE_GS_SET_CLAMP( 0, 0, 0, 0, 0, 0 );
    Map = Material->DetailMap; MipRatio = Material->MapMipRatio;
    Mode = Material->DetailMapBlendMode; Fix = Material->DetailMapBlendModeConstant;
    break;
  case NGLPASS_ENVIRONMENT:
    Clamp = SCE_GS_SET_CLAMP( 0, MaterialFlags & NGLMAT_ENV_CYLINDER ? 0 : 1, 0, 0, 0, 0 );
    Map = Material->EnvironmentMap; MipRatio = Material->MapMipRatio;
    Mode = Material->EnvironmentMapBlendMode; Fix = Material->EnvironmentMapBlendModeConstant;
    break;
  case NGLPASS_LIGHT:
    Clamp = SCE_GS_SET_CLAMP( ( MaterialFlags & NGLMAT_LIGHT_CLAMP_U ) != 0, ( MaterialFlags & NGLMAT_LIGHT_CLAMP_V ) != 0, 0, 0, 0, 0 );
    Map = Material->LightMap; MipRatio = Material->LightMapMipRatio;
    Mode = Material->LightMapBlendMode; Fix = Material->LightMapBlendModeConstant;
    break;
  default:
    NGL_ASSERT(false, "Invalid pass number.");
    break;
  }

  nglVif1StartMaterialKick();

  // Blend mode comes first, because when NGL detects Alpha TINT on a mesh it has to replace the ALPHA and TEST registers
  // with those from NGLBM_BLEND.  Call it a hack, it is.
  nglVif1AddSetBlendMode( Mode, Fix, ( MaterialFlags & NGLMAT_FORCE_Z_WRITE ) ? true : false );

  // Second comes the texture map for the pass.  Each time the material is rendered, we replace these values with the actual
  // streamed location of the texture and its mipmaps, so here we just have to leave space for 5 GS registers.
  u_int MapFlags = 0;
  if ( MaterialFlags & NGLMAT_BILINEAR_FILTER )
    MapFlags |= NGLMAP_BILINEAR_FILTER;
  else
  if ( MaterialFlags & NGLMAT_TRILINEAR_FILTER )
    MapFlags |= NGLMAP_TRILINEAR_FILTER;
  else
    MapFlags |= NGLMAP_POINT_FILTER;
  nglVif1AddSetTexture( Map, MapFlags, MipRatio );

  // Last comes everything else.
  nglVif1AddGSReg( NGL_GS_PRMODE, SCE_GS_SET_PRIM( 0, 1, 1, 0, 1, ( MaterialFlags & NGLMAT_ANTIALIAS ) != 0, 0, 0, 0 ) );
  nglVif1AddGSReg( NGL_GS_CLAMP_1, Clamp );
  nglVif1EndMaterialKick( Packet, CmdListDataPtr );

  STOP_PROF_TIMER( proftimer_section_setup_material );
}
